//! Compiled System Reference Document 5.2.1 ruleset and ECS property schema reference.
//!
//! Rules: `docs/architecture/entity_properties.md` Section 2. The data lives in
//! `data/srd_ruleset.json` (generated by `tools/build_srd_ruleset.py` under CC-BY-4.0) and is
//! embedded at compile time so this module performs zero runtime input or output.

use std::collections::BTreeMap;
use std::sync::OnceLock;

use serde::{Deserialize, Serialize};
use serde_json::Value;

/// Embedded SRD 5.2.1 ruleset and component schema JSON.
const SRD_RULESET_JSON: &str = include_str!("../data/srd_ruleset.json");

/// Every lookup domain available in [`Ruleset`].
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum RulesetDomain {
    /// Zeta's 23 ECS property component schemas.
    Component,
    /// The 12 SRD 5.2.1 character classes.
    Class,
    /// The 12 SRD 5.2.1 subclasses.
    Subclass,
    /// The 9 SRD 5.2.1 playable species.
    Species,
    /// The 4 SRD 5.2.1 backgrounds.
    Background,
    /// The 15 SRD 5.2.1 conditions.
    Condition,
    /// The 4 SRD 5.2.1 ongoing hazards.
    Hazard,
    /// The 6 core abilities.
    Ability,
    /// The 18 skills.
    Skill,
    /// The 13 damage types.
    DamageType,
    /// The 6 size categories.
    Size,
    /// The 14 creature types.
    CreatureType,
    /// The 19 standard and rare languages.
    Language,
    /// The 17 SRD 5.2.1 feats.
    Feat,
    /// The 15 closed class and monster resource pools.
    Resource,
    /// Core class features and reference spells.
    Feature,
}

impl RulesetDomain {
    /// All 16 ruleset lookup domains.
    pub const ALL: [Self; 16] = [
        Self::Component,
        Self::Class,
        Self::Subclass,
        Self::Species,
        Self::Background,
        Self::Condition,
        Self::Hazard,
        Self::Ability,
        Self::Skill,
        Self::DamageType,
        Self::Size,
        Self::CreatureType,
        Self::Language,
        Self::Feat,
        Self::Resource,
        Self::Feature,
    ];

    /// Canonical lowercase `snake_case` domain key inside `srd_ruleset.json`.
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Component => "component",
            Self::Class => "class",
            Self::Subclass => "subclass",
            Self::Species => "species",
            Self::Background => "background",
            Self::Condition => "condition",
            Self::Hazard => "hazard",
            Self::Ability => "ability",
            Self::Skill => "skill",
            Self::DamageType => "damage_type",
            Self::Size => "size",
            Self::CreatureType => "creature_type",
            Self::Language => "language",
            Self::Feat => "feat",
            Self::Resource => "resource",
            Self::Feature => "feature",
        }
    }

    /// Parses a domain name (`"class"`, `"condition"`, `"component"`, etc.).
    pub fn from_name(name: &str) -> Option<Self> {
        let normalized = name.trim().to_ascii_lowercase();
        Self::ALL
            .into_iter()
            .find(|domain| domain.as_str() == normalized)
    }
}

/// 1 authoritative ruleset definition entry returned to code or the AI DM's `inspect` tool.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct RulesetEntry {
    /// Canonical lowercase identifier matching the corresponding Rust enum variant or schema name.
    pub id: String,
    /// Display name.
    pub name: String,
    /// 1-sentence summary.
    pub summary: String,
    /// Complete authoritative SRD 5.2.1 or schema rules text.
    pub rules: String,
    /// Optional structured domain metadata (such as hit die, size, speed, or component fields).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub data: Option<Value>,
}

#[derive(Deserialize)]
struct RawRulesetFile {
    schema_version: u32,
    source: String,
    domains: BTreeMap<String, Vec<RulesetEntry>>,
}

/// Indexed, read-only SRD 5.2.1 ruleset and ECS component schema reference.
#[derive(Clone, Debug)]
pub struct Ruleset {
    schema_version: u32,
    source: String,
    by_domain: BTreeMap<RulesetDomain, Vec<RulesetEntry>>,
    index: BTreeMap<(RulesetDomain, String), usize>,
}

impl Ruleset {
    /// Returns the compiled-in SRD 5.2.1 ruleset, parsed once per process.
    ///
    /// # Panics
    /// Panics only if the embedded `srd_ruleset.json` is malformed (checked by unit tests).
    #[allow(
        clippy::expect_used,
        reason = "the embedded JSON is verified by unit tests at build time"
    )]
    pub fn srd() -> &'static Self {
        static RULESET: OnceLock<Ruleset> = OnceLock::new();
        RULESET.get_or_init(|| {
            Self::from_json(SRD_RULESET_JSON).expect("embedded srd_ruleset.json must parse cleanly")
        })
    }

    /// Parses a ruleset JSON document.
    ///
    /// # Errors
    /// Returns an error message if JSON parsing fails or contains an unknown domain key.
    pub fn from_json(json: &str) -> Result<Self, String> {
        let raw: RawRulesetFile =
            serde_json::from_str(json).map_err(|err| format!("invalid ruleset JSON: {err}"))?;
        let mut by_domain = BTreeMap::new();
        let mut index = BTreeMap::new();
        for (domain_key, entries) in raw.domains {
            let domain = RulesetDomain::from_name(&domain_key)
                .ok_or_else(|| format!("unknown ruleset domain \"{domain_key}\""))?;
            for (pos, entry) in entries.iter().enumerate() {
                if index.insert((domain, entry.id.clone()), pos).is_some() {
                    return Err(format!(
                        "duplicate ruleset entry \"{}\" in domain \"{domain_key}\"",
                        entry.id
                    ));
                }
            }
            by_domain.insert(domain, entries);
        }
        Ok(Self {
            schema_version: raw.schema_version,
            source: raw.source,
            by_domain,
            index,
        })
    }

    /// Schema format version.
    pub const fn schema_version(&self) -> u32 {
        self.schema_version
    }

    /// Attribution and source line.
    pub fn source(&self) -> &str {
        &self.source
    }

    /// Looks up 1 exact entry by domain and lowercase identifier.
    pub fn get(&self, domain: RulesetDomain, id: &str) -> Option<&RulesetEntry> {
        let pos = *self.index.get(&(domain, id.to_ascii_lowercase()))?;
        self.by_domain.get(&domain)?.get(pos)
    }

    /// All entries in `domain`.
    pub fn domain_entries(&self, domain: RulesetDomain) -> &[RulesetEntry] {
        self.by_domain.get(&domain).map_or(&[], Vec::as_slice)
    }

    /// Searches 1 domain (or all domains when `domain` is `None`) by exact id, exact name,
    /// prefix, or substring match, best matches first.
    pub fn search(
        &self,
        domain: Option<RulesetDomain>,
        query: &str,
    ) -> Vec<(RulesetDomain, &RulesetEntry)> {
        let needle = query.trim().to_ascii_lowercase();
        if needle.is_empty() {
            return domain.map_or_else(Vec::new, |d| {
                self.domain_entries(d).iter().map(|e| (d, e)).collect()
            });
        }
        let domains: Vec<RulesetDomain> =
            domain.map_or_else(|| RulesetDomain::ALL.to_vec(), |d| vec![d]);
        let mut scored: Vec<(u8, RulesetDomain, &RulesetEntry)> = Vec::new();
        for dom in domains {
            for entry in self.domain_entries(dom) {
                let id_lc = entry.id.to_ascii_lowercase();
                let name_lc = entry.name.to_ascii_lowercase();
                let rank = if id_lc == needle || name_lc == needle {
                    0
                } else if id_lc.starts_with(&needle) || name_lc.starts_with(&needle) {
                    1
                } else if id_lc.contains(&needle)
                    || name_lc.contains(&needle)
                    || entry.summary.to_ascii_lowercase().contains(&needle)
                {
                    2
                } else {
                    continue;
                };
                scored.push((rank, dom, entry));
            }
        }
        scored.sort_by(|a, b| a.0.cmp(&b.0).then_with(|| a.2.id.cmp(&b.2.id)));
        scored
            .into_iter()
            .map(|(_, dom, entry)| (dom, entry))
            .collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::catalog::{Ability, DamageType, Skill};
    use crate::protocol::properties::{
        BackgroundId, ClassId, ConditionId, CreatureType, FeatId, HazardId, LanguageId, ResourceId,
        Size, SpeciesId, SubclassId,
    };

    const ALL_COMPONENT_SCHEMAS: [&str; 23] = [
        "health",
        "armor_class",
        "size",
        "damage_affinities",
        "condition_immunities",
        "creature_type",
        "ability_scores",
        "speed",
        "senses",
        "proficiencies",
        "species",
        "background",
        "class_levels",
        "character_traits",
        "spellbook",
        "coin_purse",
        "character_bio",
        "conditions",
        "death_saves",
        "concentration",
        "active_effects",
        "resource_pools",
        "monster_profile",
    ];

    fn assert_all_present(ruleset: &Ruleset, domain: RulesetDomain, ids: &[&str]) {
        for &id in ids {
            let entry = ruleset.get(domain, id).unwrap_or_else(|| {
                panic!(
                    "missing ruleset entry \"{id}\" in domain \"{}\"",
                    domain.as_str()
                )
            });
            assert!(
                !entry.name.trim().is_empty()
                    && !entry.summary.trim().is_empty()
                    && !entry.rules.trim().is_empty(),
                "incomplete ruleset entry \"{id}\" in domain \"{}\"",
                domain.as_str()
            );
        }
        assert_eq!(
            ruleset.domain_entries(domain).len(),
            ids.len(),
            "domain \"{}\" has extra or missing entries compared to the Rust enum",
            domain.as_str()
        );
    }

    /// Exhaustiveness invariant: every single variant of every closed 5e enum and every ECS
    /// property component schema MUST have a complete definition in `srd_ruleset.json`.
    #[test]
    fn every_closed_enum_variant_and_component_schema_has_a_complete_ruleset_entry() {
        let ruleset = Ruleset::srd();
        assert_eq!(ruleset.schema_version(), 1);
        assert!(ruleset.source().contains("5.2.1"));

        assert_all_present(ruleset, RulesetDomain::Component, &ALL_COMPONENT_SCHEMAS);
        assert_all_present(
            ruleset,
            RulesetDomain::Class,
            &ClassId::ALL.map(ClassId::as_str),
        );
        assert_all_present(
            ruleset,
            RulesetDomain::Subclass,
            &SubclassId::ALL.map(SubclassId::as_str),
        );
        assert_all_present(
            ruleset,
            RulesetDomain::Species,
            &SpeciesId::ALL.map(SpeciesId::as_str),
        );
        assert_all_present(
            ruleset,
            RulesetDomain::Background,
            &BackgroundId::ALL.map(BackgroundId::as_str),
        );
        assert_all_present(
            ruleset,
            RulesetDomain::Condition,
            &ConditionId::ALL.map(ConditionId::as_str),
        );
        assert_all_present(
            ruleset,
            RulesetDomain::Hazard,
            &HazardId::ALL.map(HazardId::as_str),
        );
        assert_all_present(
            ruleset,
            RulesetDomain::Ability,
            &Ability::ALL.map(Ability::as_str),
        );
        assert_all_present(
            ruleset,
            RulesetDomain::Skill,
            &Skill::ALL.map(Skill::as_str),
        );
        assert_all_present(
            ruleset,
            RulesetDomain::DamageType,
            &DamageType::ALL.map(DamageType::as_str),
        );
        assert_all_present(ruleset, RulesetDomain::Size, &Size::ALL.map(Size::as_str));
        assert_all_present(
            ruleset,
            RulesetDomain::CreatureType,
            &CreatureType::ALL.map(CreatureType::as_str),
        );
        assert_all_present(
            ruleset,
            RulesetDomain::Language,
            &LanguageId::ALL.map(LanguageId::as_str),
        );
        assert_all_present(
            ruleset,
            RulesetDomain::Feat,
            &FeatId::ALL.map(FeatId::as_str),
        );
        assert_all_present(
            ruleset,
            RulesetDomain::Resource,
            &ResourceId::ALL.map(ResourceId::as_str),
        );
        assert!(
            !ruleset.domain_entries(RulesetDomain::Feature).is_empty(),
            "core SRD features must be populated"
        );
    }

    #[test]
    fn every_class_level_1_feature_exists_in_feature_domain() {
        let ruleset = Ruleset::srd();
        for class in ruleset.domain_entries(RulesetDomain::Class) {
            let features = class
                .data
                .as_ref()
                .and_then(|d| d.get("level_1_features"))
                .and_then(Value::as_array)
                .expect("every class lists level_1_features");
            for feat in features {
                let id = feat.as_str().expect("string feature id");
                assert!(
                    ruleset.get(RulesetDomain::Feature, id).is_some(),
                    "class {} references missing feature \"{id}\"",
                    class.id
                );
            }
        }
    }
}
